panels.css:
main{padding:0;height:1080px;display:block}
.w{height:1080px;background:linear-gradient(180deg,#FBF4EC,#F3E6D8);color:#2A1923;display:flex;flex-direction:column;padding:56px 56px 48px;box-sizing:border-box}
.k{align-self:flex-start;font-size:30px;font-weight:900;color:#fff;background:#D7263D;border-radius:999px;padding:6px 24px}
.t{font-size:64px;font-weight:900;line-height:1.2;margin-top:18px}
.t em{font-style:normal;color:#D7263D}
.bn{margin-top:26px;width:100%;border-radius:18px;box-shadow:0 8px 24px rgba(0,0,0,.12)}
.code{margin-top:30px;background:#fff;border:4px dashed #0E6E8C;border-radius:22px;padding:20px 28px;display:flex;align-items:center;gap:26px}
.code i{font-style:normal;font-size:30px;font-weight:900;color:#0E6E8C;white-space:nowrap}
.code b{font-size:72px;font-weight:900;letter-spacing:.06em;font-family:"Noto Sans Mono","Menlo",monospace}
.st{margin-top:26px;display:flex;gap:18px}
.st div{flex:1;background:#2A1923;color:#fff;border-radius:16px;padding:16px 20px;font-size:28px;font-weight:800;line-height:1.35}
.st div span{display:block;color:#F5C518;font-size:24px}
